// === Tab: mySketch ===

let lapse = 0;    // mouse timer
    let theShader;
    let W = 600

		function preload() {
      theShader = createShader(vert, frag)
    }

    function setup() {
	createCanvas(600, 600	, WEBGL);
    }

    function draw() {
      theShader.setUniform("r", [width, height]);
      theShader.setUniform("t", millis() / 1000.0);
      theShader.setUniform("m", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	shader(theShader);
      rect(0, 0, width, height);
    }

    const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`

    const frag = `
    precision mediump float;
uniform float t;       // time
uniform vec2  r;       // resolution
uniform float MM;  // in case grid is changed

void main(void){
	vec2 p = (gl_FragCoord.xy -r*2.) / min(r.x, r.y);
	vec3 destColor = vec3(0.0);
        float whichi = 0.0;
        float whichk = 0.0;
// this will be distance to nearest point
        float mydist = 100.0;
// this will be distance to next nearest point
        float mydist2 = 100.0;
	for(float i=0.0; i < 10.; i++) {
	for(float k=0.0; k < 10.; k++) {
		float j = i+1.;
                float l = k+1.;
		vec2 q = p + vec2(cos(j*t*0.6+l), sin(l*t*0.6+j)) * 0.25 + vec2(i,k)*0.25;
                 if (length(q) < mydist){
                       mydist2 = mydist;
                       mydist = length(q);
                       whichi = i;
                       whichk = k;
     	}
}
}
        destColor.x = 0.;
float fac = whichi*0.3;
float fac2 = whichk*0.3;
float dd = (mydist - mydist2)*50.;
        destColor.x = fac * mod(dd,1.);
        destColor.y = fac2 * mod(dd,1.);
	gl_FragColor = vec4(destColor,1.0);


}
`

function mousePressed(){
// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

